reversal.fixed_text:
for edge in &mut self.g.edges {
    if edge.weight.is_some() {
        edge.node.swap(0, 1);
        edge.next.swap(0, 1);
    }
}
for node in &mut self.g.nodes {
    if node.weight.is_some() {
        node.next.swap(0, 1);
    }
}

reversal.parent_text:
for edge in &mut self.g.edges {
    edge.node.swap(0, 1);
    edge.next.swap(0, 1);
}
for node in &mut self.g.nodes {
    node.next.swap(0, 1);
}
